const body = $json.body ?? {};
const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Moscow' });
return [{ json: {
  review_date: /^\d{4}-\d{2}-\d{2}$/.test(body.review_date ?? '') ? body.review_date : today,
  owner: 'hodzhakhov',
  repo: 'infra-rbac',
  trigger: $json.body ? 'api' : ($json.timestamp ? 'schedule' : 'manual'),
} }];

const texts = o => typeof o === 'string'
  ? (() => { try { const p = JSON.parse(o); return typeof p === 'object' && p ? texts(p) : [o]; } catch { return [o]; } })()
  : Array.isArray(o) ? o.flatMap(texts)
  : o && typeof o === 'object' ? Object.values(o).flatMap(texts) : [];

const tree = texts($json).join('\n');
const rolebindings = [...new Set(tree.match(/clusters\/[\w.\/-]+\/rolebindings\/[\w.-]+\.yaml/g) ?? [])].sort();
if (!rolebindings.length) throw new Error('No RoleBindings found in the repository tree');
return ['teams.yaml', ...rolebindings].map(path => ({ json: { path } }));

const texts = o => typeof o === 'string'
  ? (() => { try { const p = JSON.parse(o); return typeof p === 'object' && p ? texts(p) : [o]; } catch { return [o]; } })()
  : Array.isArray(o) ? o.flatMap(texts)
  : o && typeof o === 'object' ? Object.values(o).flatMap(texts) : [];

const p = $('Prepare').first().json;
const policy = texts($('Read policy').first().json).join('\n');
const soonDays = Number((policy.match(/expiring_soon_days:\s*(\d+)/) ?? [])[1] ?? 3);
const paths = $('Select files').all().map(i => i.json.path);
const files = $input.all().map((item, i) => ({ path: paths[i], text: texts(item.json).join('\n') }));

const teams = files.find(f => f.path === 'teams.yaml').text;
const members = new Set([...teams.matchAll(/members:\s*\[([^\]]*)\]/g)]
  .flatMap(m => m[1].split(',').map(x => x.trim()).filter(Boolean)));
const plusDays = (d, n) => new Date(Date.parse(d) + n * 86400000).toISOString().slice(0, 10);
const soonLimit = plusDays(p.review_date, soonDays);

const findings = [];
const rolebindings = files.filter(f => f.path !== 'teams.yaml');
for (const f of rolebindings) {
  const rb = {
    file: f.path,
    env: f.path.split('/')[1],
    namespace: (f.text.match(/namespace:\s*([\w-]+)/) ?? [])[1] ?? null,
    login: (f.text.match(/name:\s*([\w.-]+)@/) ?? [])[1] ?? null,
    role: (f.text.match(/roleRef:[\s\S]*?name:\s*([\w-]+)/) ?? [])[1] ?? null,
    expires_at: (f.text.match(/expires-at:\s*"?(\d{4}-\d{2}-\d{2})/) ?? [])[1] ?? null,
  };
  const add = type => findings.push({ type, ...rb });
  if (rb.role === 'admin' || (rb.role === 'edit' && rb.env === 'prod')) add('policy_violation');
  if (rb.login && !members.has(rb.login)) add('orphaned');
  if (rb.expires_at && rb.expires_at < p.review_date) add('expired');
  else if (rb.expires_at && rb.expires_at <= soonLimit) add('expiring_soon');
}

return [{ json: { ...p, expiring_soon_days: soonDays, checked: rolebindings.length, findings } }];

const c = $('Classify findings').first().json;
const agentRan = $('Investigator agent').isExecuted;
const out = agentRan ? ($('Investigator agent').first().json.output ?? '') : '';
const steps = agentRan ? ($('Investigator agent').first().json.intermediateSteps ?? []) : [];

let inv = { summary: null, findings: [] };
if (agentRan) {
  try { inv = JSON.parse(out.slice(out.indexOf('{'), out.lastIndexOf('}') + 1)); }
  catch (e) { inv = { summary: 'Агент вернул невалидный JSON, расследование не выполнено.', findings: [] }; }
}

const seen = JSON.stringify(steps.filter(s => (s.action?.tool ?? '').endsWith('list_commits')).map(s => s.observation));
const real = url => (typeof url === 'string' && url.includes('/commit/') && seen.includes(url.split('/commit/')[1].slice(0, 7))) ? url : null;
let dropped = 0;

const findings = c.findings.map(f => {
  const i = (inv.findings ?? []).find(x => x.file === f.file && x.type === f.type) ?? {};
  const grant = real(i.grant_commit), removal = real(i.team_removal_commit);
  dropped += (i.grant_commit && !grant) + (i.team_removal_commit && !removal);
  return { ...f, owner_team: i.owner_team ?? null, owner_lead: i.owner_lead ?? null,
    granted_by: grant ? i.granted_by ?? null : null, granted_at: grant ? i.granted_at ?? null : null,
    grant_commit: grant, team_removal_commit: removal, recommendation: i.recommendation ?? null };
});

const TYPES = {
  policy_violation: '🚨 Нарушение политики',
  orphaned: '👤 Сотрудник не числится в командах',
  expired: '⌛ Срок доступа истёк',
  expiring_soon: `⏰ Истекает в ближайшие ${c.expiring_soon_days} дня`,
};
const urgent = findings.filter(f => ['policy_violation', 'orphaned'].includes(f.type)).length;
const esc = v => String(v ?? '—').replace(/\|/g, '\\|').replace(/\n/g, ' ');
const link = (url, text) => url ? `[${text}](${url})` : '—';

let body = `## Ревизия доступов к Kubernetes — ${c.review_date}\n\n`;
body += `Проверено RoleBinding'ов: **${c.checked}**. Находок: **${findings.length}**, срочных: **${urgent}**.\n\n`;
if (inv.summary) body += `${inv.summary}\n\n`;
for (const [type, title] of Object.entries(TYPES)) {
  const list = findings.filter(f => f.type === type);
  if (!list.length) continue;
  body += `### ${title} (${list.length})\n\n| Кто | Где | Роль | Истекает | Выдан | Владелец | Что сделать |\n|---|---|---|---|---|---|---|\n`;
  for (const f of list) {
    const granted = f.grant_commit ? `${esc(f.granted_by)}, ${link(f.grant_commit, esc(f.granted_at))}` : '—';
    const who = esc(f.login) + (f.team_removal_commit ? ` (${link(f.team_removal_commit, 'удалён из команды')})` : '');
    const owner = f.owner_team ? `${esc(f.owner_team)} / ${esc(f.owner_lead)}` : '—';
    body += `| ${who} | \`${esc(f.file)}\` | ${esc(f.role)} | ${esc(f.expires_at)} | ${granted} | ${owner} | ${esc(f.recommendation)} |\n`;
  }
  body += '\n';
}
if (!findings.length) body += 'Нарушений не найдено.\n\n';
if (dropped) body += `> ⚠️ ${dropped} ссылок на коммиты от агента не подтвердились ответами GitHub и удалены.\n\n`;
body += `---\n_Access Review Bot · n8n + Ollama · запуск: ${c.trigger} · вызовов инструментов агентом: ${steps.length}_\n`;

const count = type => findings.filter(f => f.type === type).length;
const metrics = [
  '# HELP access_review_last_success_timestamp_seconds Unix time of the last successful access review.',
  '# TYPE access_review_last_success_timestamp_seconds gauge',
  `access_review_last_success_timestamp_seconds ${Math.floor(Date.now() / 1000)}`,
  '# HELP access_review_rolebindings_checked RoleBindings checked by the last review.',
  '# TYPE access_review_rolebindings_checked gauge',
  `access_review_rolebindings_checked ${c.checked}`,
  '# HELP access_review_findings Findings of the last review by type.',
  '# TYPE access_review_findings gauge',
  ...Object.keys(TYPES).map(type => `access_review_findings{type="${type}"} ${count(type)}`),
  '# HELP access_review_urgent_findings Urgent findings (policy_violation, orphaned) of the last review.',
  '# TYPE access_review_urgent_findings gauge',
  `access_review_urgent_findings ${urgent}`,
  '# HELP access_review_agent_tool_calls Tool calls made by the investigator agent in the last review.',
  '# TYPE access_review_agent_tool_calls gauge',
  `access_review_agent_tool_calls ${steps.length}`,
  '# HELP access_review_agent_dropped_links Commit links from the agent not confirmed by GitHub (hallucinations).',
  '# TYPE access_review_agent_dropped_links gauge',
  `access_review_agent_dropped_links ${dropped}`,
].join('\n') + '\n';

return [{ json: {
  metrics,
  owner: c.owner, repo: c.repo, review_date: c.review_date, trigger: c.trigger,
  title: `Access review ${c.review_date}: ${findings.length} findings (${urgent} urgent)`,
  body, labels: urgent ? ['access-review', 'urgent'] : ['access-review'],
  checked: c.checked, urgent, findings, dropped_links: dropped,
  agent_tools: steps.map(s => s.action?.tool).filter(Boolean),
} }];

const texts = o => typeof o === 'string'
  ? (() => { try { const p = JSON.parse(o); return typeof p === 'object' && p ? texts(p) : [o]; } catch { return [o]; } })()
  : Array.isArray(o) ? o.flatMap(texts)
  : o && typeof o === 'object' ? Object.values(o).flatMap(texts) : [];

const b = $('Build issue').first().json;
const url = (texts($('Create issue').first().json).join('\n').match(/https:\/\/github\.com\/[^\s"\\)]+\/issues\/\d+/) ?? [])[0] ?? null;
return [{ json: {
  review_date: b.review_date, trigger: b.trigger, issue_url: url,
  checked: b.checked, findings: b.findings.length, urgent: b.urgent, dropped_links: b.dropped_links,
  details: b.findings.map(f => ({ type: f.type, login: f.login, granted_by: f.granted_by, commit: f.grant_commit, owner_lead: f.owner_lead })),
  agent_tools: b.agent_tools,
} }];
